create table if not exists board_assets (id uuid primary key default gen_random_uuid(), room_id uuid references classroom_rooms(id) on delete cascade, uploaded_by uuid, file_id uuid, storage_url text, mime_type text, size_bytes int, width int, height int, created_at timestamptz default now()); alter table board_assets enable row level security; create index if not exists idx_board_assets_room on board_assets(room_id); alter publication supabase_realtime add table board_assets;
